const triggerData = $input.item.json || {};
const body = triggerData.body || triggerData.payload || triggerData || {};
const lojaId = body.loja_id ? parseInt(body.loja_id, 10) : null;

if (!lojaId || !Number.isFinite(lojaId)) {
  return { json: { hasError: true, error: 'loja_id inválido ou não informado.' } };
}

return {
  json: {
    hasError: false,
    lojaId
  }
};

const prep = $('Preparar Parametros').first()?.json || {};
if (prep.hasError) {
  return { json: { ok: false, message: prep.error } };
}

const row = $input.first()?.json || {};
if (!row.id || !row.connect_token) {
  return { json: { ok: false, message: 'Token de conexão não encontrado para esta loja.' } };
}

return {
  json: {
    ok: true,
    loja_id: row.id,
    connect_token: row.connect_token
  }
};
